-- Back up database AND private config before DDL; MariaDB DDL implicitly commits.
CREATE TABLE IF NOT EXISTS schedule_entries (id INTEGER UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, learner_id INTEGER UNSIGNED NOT NULL DEFAULT 1, weekday INTEGER NOT NULL, title VARCHAR(190) NOT NULL, subject_id VARCHAR(32) NULL, kind VARCHAR(20) NOT NULL, start_minute INTEGER NOT NULL, end_minute INTEGER NOT NULL, effective_from DATE NOT NULL, effective_until DATE NULL, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(learner_id) REFERENCES learners(id), FOREIGN KEY(subject_id) REFERENCES subjects(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS schedule_exceptions (id INTEGER UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, learner_id INTEGER UNSIGNED NOT NULL DEFAULT 1, entry_id INTEGER UNSIGNED NULL, original_date DATE NOT NULL, occurrence_date DATE NOT NULL, action VARCHAR(12) NOT NULL, title VARCHAR(190) NOT NULL, subject_id VARCHAR(32) NULL, kind VARCHAR(20) NOT NULL, start_minute INTEGER NOT NULL, end_minute INTEGER NOT NULL, created_at VARCHAR(30) NOT NULL, UNIQUE(entry_id,original_date), FOREIGN KEY(entry_id) REFERENCES schedule_entries(id), FOREIGN KEY(learner_id) REFERENCES learners(id), FOREIGN KEY(subject_id) REFERENCES subjects(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT IGNORE INTO schema_versions(version,installed_at) VALUES(2,UTC_TIMESTAMP());
